function pill(status){const color=['critical','high','lost-coverage','revoked'].includes(status)?'danger':['receiving','acknowledged','verified','rolled-back','unit-tested','acceptance-verified'].includes(status)?'success':['unknown','not-configured','visibility-gap','awaiting-data','medium','pending-approval','not-tested','implemented-unverified'].includes(status)?'warning':'info';return `<span class="pill ${color}">${h(label(status))}</span>`;}
function permitPill(status){const names={pending:tr('بانتظار الموافقة','Pending approval'),active:tr('ساري','Active'),revoked:tr('ملغى','Revoked'),expired:tr('منتهي تلقائيًا','Automatically expired')},color=status==='active'?'success':status==='pending'?'warning':'danger';return `<span class="pill ${color}">${h(names[status]||status)}</span>`;}
