function incidentRecoveryPanel(d){const evidence=phase=>phase.evidence_refs.map(h).join(' · ')||tr('لا دليل','No evidence');return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('سير عمل التعافي من الحوادث','Incident recovery workflows')}</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${table([tr('سير العمل والحادث','Workflow / incident'),tr('الاحتواء','Containment'),tr('استرداد الهوية والتكوين والأجهزة','Identity / configuration / device recovery'),tr('التحقق من آثار التهديد','Threat clearance'),tr('إعادة الاتصال','Reconnection'),tr('الدليل','Evidence')],d.items.map(item=>[`${h(item.recovery_id)}<div class="secondary mono">${h(item.incident_ref)} · ${h(item.asset.hostname||item.asset.external_id)}</div>${pill(item.workflow_state)}`,`${pill(item.containment.status)}<div class="secondary">${evidence(item.containment)}</div>`,`${pill(item.identity_recovery.status)} ${pill(item.configuration_recovery.status)} ${pill(item.device_recovery.status)}<div class="secondary">${evidence(item.identity_recovery)} · ${evidence(item.configuration_recovery)} · ${evidence(item.device_recovery)}</div>`,`${pill(item.threat_clearance.status)}<div class="secondary">${item.threat_clearance.findings_remaining} ${tr('أثر متبقٍ','remaining findings')} · ${evidence(item.threat_clearance)}</div>`,`${pill(item.reconnection.status)}<div class="secondary">${h(item.reconnection.approved_by||tr('لا موافقة','No approval'))}${item.reconnection.approved_at?` · ${h(date(item.reconnection.approved_at))}`:''}</div>`,`${evidence(item.reconnection)}<br>${button('event',tr('دليل سير التعافي','Recovery-workflow evidence'),item.event_id,'text-button')}`]),tr('لا توجد سجلات تعافٍ','No incident-recovery records'),d)}</div></section>`;}
