function firewallRulesPanel(d){const fLabel=value=>({duplicate:tr('مكررة','Duplicate'),redundant:tr('زائدة لا تُطابق أبدًا','Redundant (never matched)'),shadowed:tr('مظللة بقاعدة أسبق','Shadowed by an earlier rule'),conflict:tr('سماح يلغيه حظر','Allow overridden by block'),'any-any-allow':tr('سماح أي-إلى-أي','Any-any allow'),'broad-admin-exposure':tr('منفذ إداري مفتوح للجميع','Admin port open to any'),'broad-inbound':tr('وارد واسع','Broad inbound'),stale:tr('قاعدة قديمة','Stale rule'),'expired-exception':tr('استثناء منتهي','Expired exception'),'exception-expiring':tr('استثناء قارب الانتهاء','Exception expiring'),overlap:tr('تداخل جزئي بإجراء مختلف','Partial overlap, different action'),'east-west-broad':tr('حركة داخلية مفتوحة بالكامل','East-west fully open'),'east-west-admin':tr('منافذ إدارة مفتوحة داخليًا','Admin ports open east-west'),'open-egress':tr('حركة خارجة غير مرشحة','Unfiltered egress'),'increases-exposure':tr('يزيد التعرض','Increases exposure'),changed:tr('تغيّر','Changed'),'no-change':tr('بلا تغيير','No change')})[value]||value;return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('محلل قواعد الجدار الناري','Firewall rule analyzer')} · CG-020</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div>${d.items.map(item=>`<h3>${h(item.device_ref)} · ${h(item.vendor)}</h3><div class="secondary">${tr('القواعد','Rules')}: ${item.rules_total} · ${tr('المفعلة','enabled')} ${item.rules_enabled} · ${tr('المحللة','analysed')} ${item.rules_analysed}${item.rules_unreadable?` · ${tr('غير مقروءة دون صلاحية مدير','unreadable without elevation')} ${item.rules_unreadable}`:''} · ${tr('التقييم','evaluation')} ${h(item.evaluation)}<br>${Object.entries(item.by_type).map(([k,v])=>`${h(fLabel(k))}: ${v}`).join(' · ')||tr('لا ملاحظات','No findings')}${item.change?`<br>${tr('التغيير منذ المجموعة السابقة','Change since previous ruleset')}: ${h(fLabel(item.change.impact))} · +${item.change.added.length} −${item.change.removed.length} ~${item.change.modified.length}${item.change.new_admin_exposure.length?` · ${tr('تعرض إداري جديد','new admin exposure')}: ${item.change.new_admin_exposure.map(r=>h(r.name)).join(', ')}`:''}`:''}</div>${table([tr('الملاحظة','Finding'),tr('القاعدة','Rule'),tr('القاعدة المرتبطة','Related rule'),tr('التفاصيل','Detail')],item.findings.slice(0,60).map(f=>[`${h(fLabel(f.type))}<div class="secondary">${pill(f.severity)}</div>`,h(f.rule_name),h(f.related_rule_name||'—'),h(tr(f.detail_ar||f.detail,f.detail))]),tr('لا ملاحظات على القواعد','No rule findings'),{total:Math.min(60,item.findings_total),limit:Math.max(1,Math.min(60,item.findings_total)),offset:0})}`).join('')||`<div class="hint">${tr('لا توجد مجموعات قواعد','No rulesets')}</div>`}</div></section>`;}
