function incidentPlaybooksPanel(d){const phaseNames={triage:tr('الفرز','Triage'),investigate:tr('التحقيق','Investigate'),contain:tr('الاحتواء','Contain'),recover:tr('الاسترداد','Recover'),review:tr('المراجعة','Review')};const playbooks=table([tr('نوع الحادث','Incident type'),tr('الإشارات','Signals'),tr('مسارات الدليل','Evidence paths'),tr('مسار الاستجابة الآمن','Safe response path'),tr('الأتمتة','Automation')],d.items.map(item=>[`${h(tr(item.title_ar,item.title_en))}<div class="secondary mono">${h(item.id)} · v${item.version}</div>`,item.signals.map((s,i)=>h(tr(item.signals_ar?.[i]||s,s))).join('<br>'),item.evidence_paths.map(path=>`<span class="mono">${h(path)}</span>`).join('<br>'),item.phases.map(phase=>`<strong>${h(phaseNames[phase.id]||phase.id)}</strong>: ${h(tr((phase.steps_ar||[]).every(Boolean)&&phase.steps_ar?.length?phase.steps_ar.join(' · '):phase.steps.join(' · '),phase.steps.join(' · ')))}`).join('<br>'),`${pill(item.automation.risk)} ${h(tr('إنشاء قضية محلية فقط بعد MFA وموافقة مستقلة','Local case creation only after MFA and independent approval'))}<div class="secondary">${h(tr('لا تغيير خارجي','No external change'))}</div>${canWrite()?button('playbook-request',tr('طلب تشغيل','Request run'),item.id,'small primary'):''}`]),tr('لا توجد Playbooks','No playbooks'),{total:d.items.length,limit:d.items.length,offset:0});const runs=table([tr('الطلب','Run'),tr('Playbook والتنبيه','Playbook / alert'),tr('الحالة والموافقة','State / approval'),tr('لقطة الدليل','Evidence snapshot'),tr('الإجراء','Action')],d.runs.map(run=>[`<span class="mono">${h(run.id.slice(0,8))}</span><div class="secondary">${h(run.requested_by_name)} · ${h(date(run.requested_at))}</div>`,`<span class="mono">${h(run.playbook_id)} v${run.playbook_version}</span><div class="secondary">${button('alert',h(run.alert_id.slice(0,8)),run.alert_id,'text-button')}</div>`,`${pill(run.status)}<div class="secondary">${h(run.approved_by_name||tr('بانتظار مسؤول آخر','Awaiting another administrator'))}</div>`,`<span class="mono">${h(run.evidence_snapshot.sha256)}</span><div class="secondary">${run.evidence_snapshot.evidence_ids.length} ${tr('مراجع','references')}</div>`,`${state.user.role==='admin'&&run.status==='pending'&&run.requested_by!==state.user.id?button('playbook-approve',tr('اعتماد','Approve'),run.id,'small primary')+button('playbook-deny',tr('رفض','Deny'),run.id,'small danger'):''}${state.user.role==='admin'&&run.status==='approved'?button('playbook-execute',tr('إنشاء القضية المحلية','Create local case'),run.id,'small primary'):''}${run.case_id?button('case',tr('فتح القضية','Open case'),run.case_id,'text-button'):''}`]),tr('لا توجد طلبات تشغيل','No playbook runs'),{total:d.runs.length,limit:d.runs.length||1,offset:0});return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('Playbooks الحوادث ومسارات الأدلة','Incident playbooks and evidence paths')} · CG-035</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar||d.claim,d.claim))}</div><div class="secondary">${tr('أنواع الحوادث المدعومة','Supported incident types')}: ${d.coverage.supported_incident_types} · ${tr('المغطاة','covered')}: ${d.coverage.playbooks} · ${tr('غير المغطاة','uncovered')}: ${d.coverage.uncovered_supported_types.length}</div>${playbooks}<div class="divider"></div><h3>${tr('طلبات الأتمتة منخفضة الخطورة','Low-risk automation requests')}</h3>${runs}</div></section>`;}
