const aiActionText=value=>({'network.block-ip':tr('حظر عنوان IP','Block IP'),'network.block-port':tr('حظر منفذ','Block port'),'endpoint.block-app':tr('حظر تطبيق','Block application'),'dns.block-domain':tr('حظر نطاق DNS','Block DNS domain'),'endpoint.stop-service':tr('إيقاف خدمة','Stop service'),'endpoint.quarantine-file':tr('عزل ملف','Quarantine file'),'endpoint.isolate-device':tr('عزل جهاز','Isolate device')})[value]||value;
const aiProposalStatus=value=>({proposed:tr('مقترح بانتظار إنسان','Proposed, awaiting a human'),promoted:tr('رُقّي إلى طلب بشري','Promoted to a human request'),dismissed:tr('رُفض من إنسان','Dismissed by a human')})[value]||value;
const aiRejectText=value=>({ai_raw_command_rejected:tr('أمر خام مرفوض','raw command rejected'),ai_action_not_in_catalog:tr('إجراء خارج الكتالوج','action not in catalog'),ai_action_not_proposable:tr('إجراء غير مسموح للذكاء الاصطناعي','action not allowed for AI'),ai_target_outside_alert_asset:tr('هدف خارج أصل التنبيه','target outside the alert asset'),ai_disruptive_action_blocked_on_critical_asset:tr('إجراء معطّل على أصل حرج','disruptive action on a critical asset'),ai_proposal_limit_reached:tr('تجاوز حد الاقتراحات المفتوحة','open proposal limit reached'),ai_suggestion_not_found:tr('اقتراح غير موجود','suggestion not found')})[value]||value;
const aiTarget=t=>h(Object.entries(t||{}).map(([k,v])=>`${k}=${typeof v==='object'?JSON.stringify(v):v}`).join(' · '));
function aiProposalsPanel(d){return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('اقتراحات إجراءات الذكاء الاصطناعي','AI action proposals')} · CG-039</h2></div><div class="panel-body"><div class="hint">${tr('المحلل لا يرسل أوامر أبدًا: يقترح فقط إجراءً من كتالوج الاستجابة المحدود بهدف محدد النوع لأصل التنبيه نفسه. تُرفض حقول الأوامر والنصوص الشبيهة بالأوامر والإجراءات خارج القائمة المسموحة والأهداف خارج أصل التنبيه والإجراءات المعطّلة على الأصول الحرجة وأكثر من ثلاثة اقتراحات مفتوحة لكل تنبيه، وتُسجّل في التدقيق. لا يفعل الاقتراح شيئًا حتى يرقّيه محلل أو مسؤول إلى طلب عادي يحتاج موافقًا مستقلًا وMFA حديثًا؛ ولا يستطيع الذكاء الاصطناعي الموافقة أو التنفيذ.',d.claim)}</div>
  ${table([tr('الإجراء','Action'),tr('الأصل','Asset'),tr('المصدر','Origin'),tr('الحالة','Status'),tr('قرار بشري','Human decision')],d.items.map(p=>[`<strong>${h(aiActionText(p.action_type))}</strong><div class="secondary mono">${aiTarget(p.target)}</div><div class="secondary">${h(tr(p.rationale_ar||p.rationale,p.rationale))}</div>`,button('asset',h(p.asset.hostname||p.asset.external_id),p.asset.id,'text-button'),h(p.origin==='local-analyst'?tr('المحلل المحلي','Local analyst'):tr('موصل نموذج','Model connector')),`<span class="pill ${p.status==='proposed'?'warning':p.status==='promoted'?'success':'info'}">${h(aiProposalStatus(p.status))}</span>${p.action_id?`<div class="secondary mono">${h(p.action_id)} · ${h(p.action_status||'')}</div>`:''}`,p.status==='proposed'?`${button('ai-promote',tr('ترقية إلى طلب','Promote to request'),p.id,'small')} ${button('ai-dismiss',tr('رفض','Dismiss'),p.id,'small ghost')}`:h(p.decided_by||'—')]),tr('لا توجد اقتراحات بعد','No proposals yet'),{total:d.items.length,limit:d.items.length,offset:0})}
  <h3>${tr('محاولات الذكاء الاصطناعي المرفوضة','Rejected AI attempts')}</h3>${d.rejected.length?`<ul class="factor-list">${d.rejected.slice(0,20).map(r=>`<li>${h(aiRejectText(r.reason))} · <span class="secondary">${h(date(r.at))} · ${h(r.origin==='local-analyst'?tr('المحلل المحلي','Local analyst'):tr('موصل نموذج','Model connector'))}</span></li>`).join('')}</ul>`:`<div class="secondary">${tr('لا توجد محاولات مرفوضة','No rejected attempts')}</div>`}</div></section>`;}
