function qualityMetricsPanel(d){const n=v=>v===null||v===undefined?tr('غير مُقاس','not measured'):String(v),pct=v=>v===null||v===undefined?tr('غير مُقاس','not measured'):`${Math.round(v*1000)/10}%`,mins=v=>{if(v===null||v===undefined)return tr('غير مُقاس','not measured');const x=Math.round(v*10)/10;return tr(`${x} دقيقة`,`${x} min`);},q=d.detection_quality,t=d.timing,c=d.device_coverage,r=d.rule_coverage,f=d.response_failures;
  const stateName=v=>({measured:tr('مُقاسة','Measured'),noisy:tr('مزعجة (دقة أقل من 50%)','Noisy (precision below 50%)'),'not-triaged':tr('غير مصنفة','Not triaged'),'no-hits-in-window':tr('لا إصابات في الفترة','No hits in window'),'no-evidence-received':tr('لا أدلة من نوعها','No evidence of its kind')})[v]||v,stateCls=v=>v==='measured'?'success':v==='noisy'||v==='no-evidence-received'?'warning':'info';
  const card=(label,value,sub)=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${h(value)}</div><div class="stat-foot">${h(sub)}</div></div>`;
  return `<div class="divider"></div><section class="panel" data-quality-metrics><div class="panel-head"><h2>${tr('جودة الكشف والاستجابة','Detection and response quality')} · CG-058</h2><span class="secondary">${tr(`آخر ${d.window_days} يومًا`,`last ${d.window_days} days`)}</span></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div>
    <div class="stats">${card(tr('الدقة','Precision'),pct(q.precision),tr(`${q.dispositioned} مصنفة من ${q.alerts}`,`${q.dispositioned} of ${q.alerts} dispositioned`))}${card(tr('الإيجابيات الكاذبة','False positives'),pct(q.false_positive_rate),tr(`${q.false_positive} تنبيه`,`${q.false_positive} alerts`))}${card('MTTD',mins(t.mttd_minutes),tr(`${t.mttd_samples} عينة`,`${t.mttd_samples} samples`))}${card('MTTR',mins(t.mttr_minutes),tr(`${t.mttr_samples} عينة`,`${t.mttr_samples} samples`))}${card(tr('تغطية الأجهزة','Device coverage'),pct(c.coverage),tr(`${c.assets_on_receiving_sources} من ${c.assets} أصل`,`${c.assets_on_receiving_sources} of ${c.assets} assets`))}${card(tr('تغطية القواعد','Rule coverage'),pct(r.coverage),tr(`${r.rules_with_evidence_received} من ${r.catalog_rules} قاعدة`,`${r.rules_with_evidence_received} of ${r.catalog_rules} rules`))}${card(tr('فشل إجراءات الاستجابة','Response action failures'),pct(f.action_failure_rate),tr(`${f.failed_actions} من ${f.completed_actions} مكتمل`,`${f.failed_actions} of ${f.completed_actions} completed`))}${card(tr('فشل مهام الموصلات','Connector job failures'),pct(f.job_failure_rate),tr(`${f.failed_jobs} من ${f.connector_jobs}`,`${f.failed_jobs} of ${f.connector_jobs}`))}</div>
    <p class="secondary">MTTA: ${h(mins(t.mtta_minutes))} · ${tr('متوسط التصنيف','Mean triage')}: ${h(mins(t.mean_triage_minutes))} · ${tr('غير مصنفة','Not triaged')}: ${q.not_triaged}</p>
    ${table([tr('القاعدة','Rule'),tr('الحالة','State'),tr('التنبيهات','Alerts'),tr('صحيح / حميد / كاذب','True / benign / false'),tr('الدقة','Precision'),'MTTD','MTTR'],d.by_rule.map(x=>[`<span class="mono">${h(x.rule_id)}</span>`,`<span class="pill ${stateCls(x.state)}">${h(stateName(x.state))}</span>`,x.alerts,`${x.true_positive} / ${x.benign_true_positive} / ${x.false_positive}`,h(pct(x.precision)),h(mins(x.mean_detect_minutes)),h(mins(x.mean_respond_minutes))]),tr('لا توجد قواعد.','No rules.'),{total:d.by_rule.length,limit:d.by_rule.length,offset:0})}
    ${f.by_connector.length?table([tr('الموصل','Connector'),tr('المهام','Jobs'),tr('نجحت','Succeeded'),tr('فشلت','Failed'),tr('نسبة الفشل','Failure rate')],f.by_connector.map(x=>[`<span class="mono">${h(x.connector_id)}</span>`,x.queued,x.succeeded,x.failed,h(pct(x.failure_rate))]),'',{total:f.by_connector.length,limit:f.by_connector.length,offset:0}):''}
  </div></section>`;}
