function hypothesesPanel(d,kinds){const st=v=>({draft:tr('مسودة','Draft'),tested:tr('مختبرة يدويًا','Manually tested'),approved:tr('معتمدة وفعالة','Approved and active'),rejected:tr('مرفوضة','Rejected'),retired:tr('موقوفة','Retired')})[v]||v,cls=v=>v==='approved'?'success':v==='tested'?'info':v==='draft'?'warning':'danger';
  const ops=d.operators.map(o=>`<option value="${o}">${o}</option>`).join('');
  return `<div class="divider"></div><section class="panel" data-hypotheses><div class="panel-head"><h2>${tr('فرضيات الكشف من الأدلة المنشورة وDetection-as-Code','Detection hypotheses from published evidence · Detection-as-Code')} · CG-065 / CG-111</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div><div class="hint">${h(tr(d.detection_as_code.claim_ar,d.detection_as_code.claim))}</div>
    ${table([tr('القاعدة','Rule'),tr('الفرضية والضبط','Hypothesis / tuning'),tr('المصدر','Source'),tr('الحالة والجودة','Status / quality'),tr('اختبار الوحدة والجودة','Unit / quality test'),''],d.items.map(x=>[`<span class="mono">${h(x.rule_id)}</span><div class="secondary" data-rule-versions>${tr('الإصدار العامل','Running version')}: ${x.active_version?`v${x.active_version}`:'—'} · ${tr('الأحدث','Latest')}: v${x.version}</div><div class="secondary">${x.versions.map(v=>`v${v.version} ${v.signature_valid?tr('موقّع ✓','signed ✓'):tr('توقيع غير صالح','invalid signature')}`).join(' · ')}</div>${state.user.role==='admin'&&x.versions.some(v=>v.version!==x.active_version)?x.versions.filter(v=>v.version!==x.active_version).map(v=>button('hypothesis-rollback',tr(`استعادة v${v.version}`,`Roll back to v${v.version}`),`${x.id}:${v.version}`,'small ghost')).join(''):''}`,`${h(x.title)}<div class="secondary mono" dir="ltr">${h(x.logic.kind)}: ${h(x.logic.conditions.map(c=>`${c.field} ${c.operator} ${c.value===null?'':JSON.stringify(c.value)}`).join(x.logic.match==='any'?' OR ':' AND '))}</div><div class="secondary">${tr('البيئة','Environment')}: ${h(x.environment_tuning.environment)} · ${tr('الاستثناءات','exclusions')}: ${x.environment_tuning.exclusions.length}</div>`,`<span class="mono" dir="ltr">${h(x.source_ref)}</span><div class="secondary">${h(x.technique_ids.join(', '))}</div>`,`<span class="pill ${cls(x.status)}">${st(x.status)}</span><div class="secondary">${tr('الإيجابيات الكاذبة','False positives')}: ${x.quality.false_positives}/${x.quality.dispositioned} · ${h(x.quality.state)} · ${tr('الميزانية','budget')} ${x.quality.budget_percent}%</div>`,x.test?`${x.test.passed?tr('نجح','Passed'):tr('فشل','Failed')} · ${x.test.samples} ${tr('عينة','samples')}<div class="secondary">${tr(`كانت ستنبه على ${x.test.replay.would_alert} من ${x.test.replay.events} حدثًا في 30 يومًا`,`would alert on ${x.test.replay.would_alert} of ${x.test.replay.events} events in 30 days`)} · ${h(x.test.quality_gate?.false_positive_analysis?.state||'not-measured')}</div>`:tr('لم تُختبر','Not tested'),x.status==='tested'&&state.user.role==='admin'?`${button('hypothesis-approve',tr('اعتماد','Approve'),String(x.id),'small primary')}${button('hypothesis-reject',tr('رفض','Reject'),String(x.id),'small ghost')}`:x.status==='approved'&&state.user.role==='admin'?button('hypothesis-retire',tr('إيقاف','Retire'),String(x.id),'small ghost'):'']),tr('لا توجد فرضيات بعد.','No hypotheses yet.'),{total:d.items.length,limit:d.items.length,offset:0})}
    ${canWrite()?`<h3>${tr('فرضية جديدة','New hypothesis')}</h3><form data-form="hypothesis" class="form-grid"><label>${tr('العنوان','Title')}<input name="title" required></label><label>${tr('نوع المصدر','Source type')}<select name="source_type"><option value="advisory">${tr('نشرة رسمية','Advisory')}</option><option value="incident-study">${tr('دراسة حادثة','Incident study')}</option><option value="threat-report">${tr('تقرير تهديد','Threat report')}</option><option value="internal-observation">${tr('ملاحظة داخلية','Internal observation')}</option></select></label><label>${tr('مرجع المصدر (رابط HTTPS أو معرف الدراسة)','Source reference (HTTPS link or study ID)')}<input name="source_ref" required dir="ltr"></label><label>${tr('تقنيات ATT&CK (مفصولة بفواصل)','ATT&CK techniques (comma separated)')}<input name="technique_ids" dir="ltr" placeholder="T1059.001"></label><label>${tr('الخطورة','Severity')}<select name="severity"><option value="medium">medium</option><option value="high">high</option><option value="low">low</option><option value="critical">critical</option></select></label><label>${tr('بيئة الضبط','Tuning environment')}<select name="tuning_environment"><option value="all">all</option><option value="production">production</option><option value="staging">staging</option><option value="lab">lab</option><option value="development">development</option></select></label><label>${tr('ميزانية الإيجابيات الكاذبة %','False-positive budget %')}<input name="false_positive_budget_percent" type="number" min="0" max="100" value="20"></label><label>${tr('نوع الدليل','Evidence kind')}<select name="kind">${kinds.map(k=>`<option value="${k}">${k}</option>`).join('')}</select></label><label>${tr('الحقل','Field')}<input name="field" required dir="ltr" placeholder="command_line"></label><label>${tr('المعامل','Operator')}<select name="operator">${ops}</select></label><label>${tr('القيمة','Value')}<input name="value" dir="ltr"></label><label>${tr('حقل استثناء البيئة (اختياري)','Environment exclusion field (optional)')}<input name="exclusion_field" dir="ltr"></label><label>${tr('قيمة الاستثناء','Exclusion value')}<input name="exclusion_value" dir="ltr"></label><label>${tr('سبب الاستثناء','Exclusion reason')}<input name="exclusion_reason"></label><label>${tr('المبرر','Rationale')}<input name="rationale" required></label><button class="primary" type="submit">${tr('حفظ كمسودة','Save as draft')}</button></form>
    <h3>${tr('اختبار يدوي لفرضية','Manual test of a hypothesis')}</h3><form data-form="hypothesis-test" class="form-grid"><label>${tr('رقم الفرضية','Hypothesis number')}<input name="id" type="number" min="1" required></label><label>${tr('العينات (JSON: details وexpect)','Samples (JSON: details and expect)')}<textarea name="samples" required dir="ltr" rows="4">[{"details":{},"expect":"match"},{"details":{},"expect":"no-match"}]</textarea></label><label>${tr('ملاحظات المراجعة','Review notes')}<input name="notes"></label><label class="checkbox"><input type="checkbox" name="manual_review" required> ${tr('أقر بأني راجعت الفرضية ونتائجها يدويًا','I reviewed the hypothesis and its results manually')}</label><button class="primary" type="submit">${tr('تشغيل الاختبار','Run test')}</button></form>`:''}
  </div></section>`;}
function correlationRulesPanel(d){const st={active:tr('فعالة','Active'),draft:tr('مسودة','Draft'),disabled:tr('معطلة','Disabled')};
  const stage=x=>`${h(x.name)}: <span dir="ltr">${h(x.kind)}${x.items?'['+h(x.items)+']':''}</span> ${x.distinct_field?tr(`≥ ${x.min_distinct} مميز (${x.distinct_field})`,`≥ ${x.min_distinct} distinct ${x.distinct_field}`):`≥ ${x.min_count}`}${x.conditions.length?' · '+x.conditions.map(c=>`<span dir="ltr">${h(c.field)} ${h(c.operator)} ${h(JSON.stringify(c.value))}</span>`).join(' · '):''} · ${tr('مفتاح','key')} <span dir="ltr">${h(x.key)}</span>`;
  return `<div class="divider"></div><section class="panel" data-correlation-rules><div class="panel-head"><h2>${tr('قواعد الارتباط ذات الحالة','Stateful correlation rules')} · CG-161</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div>
  ${table([tr('القاعدة','Rule'),tr('المراحل','Stages'),tr('النافذة','Window'),tr('قائمة السماح','Allow-list'),tr('اختبار العينات','Sample test'),tr('إعادة التشغيل (7 أيام)','Replay (7 days)'),tr('الحالة','Status')],d.rules.map(r=>[`<strong dir="ltr">${h(r.id)}</strong><br>${h(tr(r.title_ar||r.title,r.title))}`,r.stages.map(stage).join('<br>'),`${Math.round(r.window_seconds/60)} ${tr('دقيقة','min')} · ${r.ordered?tr('بالترتيب','ordered'):tr('دون ترتيب','unordered')}`,r.allow_keys.length?`<span dir="ltr">${h(r.allow_keys.join(', '))}</span>`:'—',`<span class="pill ${r.test.passed?'success':'danger'}">${r.test.passed?tr('ناجح','Passed'):tr('فاشل','Failed')}</span> ${tr('خبيثة','malicious')} ${r.test.malicious_fired}/${r.test.malicious_total} · ${tr('سليمة أطلقت','benign fired')} ${r.test.benign_fired}/${r.test.benign_total}`,`${r.replay.matches} ${tr('تطابق','matches')} · ${r.replay.keys} ${tr('مفتاح','keys')}`,`<span class="pill ${r.status==='active'?'success':'warning'}">${st[r.status]}</span>${r.builtin?' '+tr('مدمجة','built-in'):''}`]),'',{total:d.rules.length,limit:d.rules.length,offset:0})}
  <p class="secondary">${tr('إنشاء قاعدة','Create a rule')}: <span dir="ltr">POST /api/correlation-rules</span> · ${tr('الاعتماد','Approve')}: <span dir="ltr">POST /api/correlation-rules/&lt;id&gt;/approve</span> ${tr('(مسؤول آخر + MFA)','(another admin + MFA)')} · <a href="${h(d.reference.url)}" target="_blank" rel="noopener noreferrer">${h(d.reference.id)}</a></p></div></section>`;}
const dcState={proposed:tr('مقترح — ينتظر اعتماد مسؤول ثانٍ','Proposed — awaiting a second administrator'),active:tr('فعال','Active'),expired:tr('منتهي','Expired'),retired:tr('متقاعد','Retired')};
const dcIso={'no-privileges':tr('بلا صلاحيات','No privileges'),'logon-denied-or-disabled':tr('الدخول ممنوع أو معطل','Logon denied or disabled'),'monitored-sign-in':tr('الدخول مراقب','Sign-in monitored'),'read-only':tr('للقراءة فقط','Read-only'),'outside-production-data':tr('خارج بيانات الإنتاج','Outside production data'),'object-access-audit':tr('تدقيق الوصول (SACL)','Object access audit (SACL)'),'authenticates-nowhere':tr('لا يصادق في أي مكان','Authenticates nowhere')};
function deceptionPanel(d){
  return `<div class="divider"></div><section class="panel" data-deception><div class="panel-head"><h2>${tr('الخداع عالي الإشارة (طُعم)','High-signal deception (decoys)')} · CG-164</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div>
  <p class="secondary">${Object.entries(d.types).map(([k,t])=>`${h(tr(t.title_ar,t.title))} (<span dir="ltr">${h(t.d3fend)}</span>): ${t.required.map(x=>dcIso[x]||h(x)).join(tr('، ',', '))}`).join(' · ')}</p>
  ${d.decoys.length?table([tr('الطُعم','Decoy'),tr('النوع','Type'),tr('الموضع والمالك','Placement / owner'),tr('العزل','Isolation'),tr('الاعتماد','Approval'),tr('الحالة','State'),tr('الاستخدامات','Touches')],d.decoys.map(x=>[`<span dir="ltr">${h(x.ref_display)}</span>`,`${h(tr(d.types[x.type].title_ar,d.types[x.type].title))} <span dir="ltr">${h(x.d3fend)}</span>`,`${h(x.placement)}<br>${h(x.owner)}`,x.isolation.map(i=>dcIso[i]||h(i)).join(tr('، ',', ')),`${h(x.authorization_ref)}${x.approved_by?'<br>'+tr('اعتمده','approved by')+' '+h(x.approved_by):''}${x.expires_at?'<br>'+tr('ينتهي','expires')+' '+date(x.expires_at):''}`,`<span class="pill ${x.state==='active'?'success':x.state==='proposed'?'warning':'info'}">${dcState[x.state]}</span>`,x.triggers.n?`<span class="pill danger">${x.triggers.n}</span> ${date(x.triggers.last)}`:'0']),'',{total:d.decoys.length,limit:d.decoys.length,offset:0}):`<p class="secondary">${tr('لا طُعم مسجّل.','No decoys registered.')}</p>`}
  <p class="secondary">${tr('اقتراح','Propose')}: <span dir="ltr">POST /api/deception</span> · ${tr('اعتماد','Approve')}: <span dir="ltr">POST /api/deception/&lt;id&gt;/approve</span> ${tr('(مسؤول آخر + MFA)','(another admin + MFA)')} · ${d.references.map(r=>`<a href="${h(r.url)}" target="_blank" rel="noopener noreferrer">${h(r.id)}</a>`).join(' · ')}</p></div></section>`;}
