const lcStage={draft:tr('مسودة','Draft'),tested:tr('مختبرة','Tested'),canary:tr('كناري (ظل، دون تنبيهات)','Canary (shadow, no alerts)'),published:tr('منشورة','Published'),approved:tr('منشورة','Published'),'rolled-back':tr('تراجع تلقائي','Rolled back automatically'),suspended:tr('موقوفة لضجيجها','Suspended for noise'),retired:tr('متقاعدة','Retired'),rejected:tr('مرفوضة','Rejected')};
const lcGate={canary_elapsed:tr('انتهت الفترة','Period ended'),reviewed_enough:tr('المراجعة كافية','Enough reviewed'),false_positives_within_budget:tr('الإيجابيات الكاذبة ضمن الميزانية','False positives within budget'),noise_within_limit:tr('الضجيج ضمن الحد','Noise within limit')};
function detectionLifecyclePanel(d){const rows=(d.items||[]).filter(x=>x.lifecycle);if(!rows.length)return '';
  return `<div class="divider"></div><section class="panel" data-detection-lifecycle><div class="panel-head"><h2>${tr('دورة حياة محتوى الكشف','Detection content lifecycle')} · CG-165</h2></div><div class="panel-body"><div class="hint">${tr('اختبار بالعينات، ثم اختبار خلفي على سجلات مختبرية يجب أن تُطلق فيه القاعدة، ثم توقيع واعتماد مستقل، ثم كناري في الظل تُراجع نتائجه مقابل ميزانية الإيجابيات الكاذبة، ثم نشر. وإذا تجاوزت النسخة المنشورة حد التنبيهات اليومي أو ميزانية الإيجابيات الكاذبة تُعاد تلقائيًا إلى آخر نسخة موقعة سليمة.','Sample test, then a lab backtest in which the rule must fire, signing and independent approval, a shadow canary whose hits are reviewed against the false-positive budget, then publication. A published version over its daily alert limit or false-positive budget is rolled back automatically to the last good signed version.')}</div>
  ${table([tr('القاعدة','Rule'),tr('المرحلة','Stage'),tr('الاختبار الخلفي','Lab backtest'),tr('الكناري','Canary'),tr('بوابات النشر','Publication gates'),tr('حد التنبيهات اليومي','Daily alert limit'),tr('التراجع التلقائي','Automatic rollbacks')],rows.map(x=>{const l=x.lifecycle,c=l.canary;return [`<strong dir="ltr">${h(x.rule_id)}</strong><br>${h(x.title)}`,`<span class="pill ${['rolled-back','suspended'].includes(l.stage)?'danger':l.stage==='canary'?'warning':['published','approved'].includes(l.stage)?'success':'info'}">${lcStage[l.stage]||h(l.stage)}</span>${x.active_version?' v'+x.active_version:''}`,l.backtest?`${h(l.backtest.source_name)}: ${l.backtest.would_alert} / ${l.backtest.events}`:tr('لم يُجرَ','Not run'),c?`v${c.version} · ${date(c.until)}<br>${tr('نتائج','hits')} ${c.hits} · ${tr('روجعت','reviewed')} ${c.reviewed} · FP ${c.false_positive_rate===null?'—':Math.round(c.false_positive_rate*100)+'%'}`:'—',l.gates?Object.entries(l.gates).map(([k,v])=>`<span class="pill ${v?'success':'warning'}">${v?'✓':'✗'} ${lcGate[k]}</span>`).join(' '):'—',String(l.max_alerts_per_day),l.auto_rollbacks.length?l.auto_rollbacks.map(a=>`v${a.from_version} → ${a.to_version?'v'+a.to_version:tr('موقوفة','suspended')} <span class="secondary">${h(a.reason)}</span>`).join('<br>'):'—'];}),'',{total:rows.length,limit:rows.length,offset:0})}
  <p class="secondary">${tr('مراجعة نتيجة كناري','Review a canary hit')}: <span dir="ltr">POST /api/hypotheses/&lt;id&gt;/canary-review</span> · ${tr('النشر','Publish')}: <span dir="ltr">POST /api/hypotheses/&lt;id&gt;/promote</span> ${tr('(مسؤول + MFA)','(admin + MFA)')}</p></div></section>`;}
