function attackMappingPanel(d){const s=d.summary,st={'sensor-active':tr('الحساس يعمل','Sensor active'),'no-sensor-data':tr('لا بيانات من الحساس','No sensor data'),'built-in':tr('داخلي','Built-in')},cat={detection:tr('كشف','Detection'),posture:tr('وضع أمني','Posture'),operational:tr('تشغيلي','Operational')};
  return `<div class="divider"></div><section class="panel" data-attack-mapping><div class="panel-head"><h2>${tr('خريطة ATT&CK وD3FEND','ATT&CK and D3FEND mapping')} · CG-110</h2><a class="button small ghost" href="/api/attack-mapping/navigator-layer" download="cyberguard-attack-layer.json">${tr('تنزيل طبقة ATT&CK Navigator','Download ATT&CK Navigator layer')}</a></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div>
    <div class="stats">${[[tr('قواعد مربوطة','Mapped rules'),s.rules],[tr('تقنيات ATT&CK','ATT&CK techniques'),s.techniques],[tr('تقنيات بحساس يعمل','Techniques with sensor data'),s.techniques_with_sensor_data],[tr('تقنيات D3FEND','D3FEND techniques'),s.d3fend_techniques],[tr('قواعد أطلقت تنبيهات','Rules that fired'),s.rules_fired]].map(([l,v])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-value">${v}</div></div>`).join('')}</div>
    ${table([tr('القاعدة','Rule'),tr('الاستخدام','Use case'),'ATT&CK',tr('الحساس والحدث','Sensor and event'),'D3FEND',tr('الحالة','Status'),tr('اختبار النجاح','Success test')],d.rows.map(r=>[`<span class="mono">${h(r.rule)}</span><div class="secondary">${cat[r.category]}</div>`,h(tr(r.use_case_ar,r.use_case)),`<span class="mono" dir="ltr">${h(r.techniques.join(', ')||'—')}</span>`,tr(`<span class="mono" dir="ltr">${h(r.sensor_kinds.join(", ")||"—")}</span>`,`${h(r.sensor)}<div class="secondary">${h(r.indicator)}</div>`),`<span class="mono" dir="ltr">${h([...r.d3fend_detect,...r.d3fend_respond].join(', ')||'—')}</span>`,`${st[r.status]}<div class="secondary">${r.alerts_total} ${tr('تنبيه','alerts')}</div>`,`<span class="mono secondary" dir="ltr">${h(r.test.split(':')[0])}</span>`]),tr('لا توجد قواعد.','No rules.'),{total:d.rows.length,limit:d.rows.length,offset:0})}
  </div></section>`;}
