const uncertaintyName={low:tr('منخفض','Low'),medium:tr('متوسط','Medium'),high:tr('مرتفع','High')};
function groundingHtml(a){if(!a.grounded_claims)return '';return `<div class="detail-section" data-grounding><h3>${tr('المصادر المؤرخة وعدم اليقين','Dated sources and uncertainty')} · CG-122</h3><p class="secondary">${h(tr(a.grounding_claim_ar,a.grounding_claim))} ${tr('دورك','Your role')}: ${h(a.redaction.role)} · ${a.redaction.redacted_values} ${tr('قيمة مخفية','values hidden')}</p>
  ${table([tr('الادعاء','Claim'),tr('عدم اليقين','Uncertainty'),tr('الأسباب','Reasons'),tr('النسخ المستشهد بها','Cited snapshots')],a.grounded_claims.map(c=>[({what_happened:tr('ماذا حدث','What happened'),why_suspicious:tr('لماذا هو مشبوه','Why suspicious'),confidence:tr('الثقة','Confidence'),solution:tr('الحل','Solution')})[c.section]||h(c.section),`<span class="pill ${c.uncertainty.level==='high'?'danger':c.uncertainty.level==='medium'?'warning':'success'}">${uncertaintyName[c.uncertainty.level]}</span>`,c.uncertainty.reasons.map(r=>h(tr(r.ar,r.en))).join('<br>')||'—',c.citations.filter(x=>x.snapshot_id).map(x=>`<span class="mono" dir="ltr">${h(x.source_id.split(':')[0])} ${h(x.sha256.slice(0,10))}… ${date(x.captured_at)}</span>`).join('<br>')]),'',{total:a.grounded_claims.length,limit:a.grounded_claims.length,offset:0})}</div>`;}
