function dataContractPanel(d){const n=v=>v===null||v===undefined?'—':String(v),pc=v=>v===null||v===undefined?'—':v+'%';
  return `<div class="divider"></div><section class="panel" data-data-contracts><div class="panel-head"><h2>${tr('عقد بيانات الأحداث لكل موصل','Event data contract per connector')} · CG-162</h2></div><div class="panel-body"><div class="hint">${h(tr(d.claim_ar,d.claim))}</div>
  ${table([tr('الموصل','Connector'),tr('العقد المعلن','Declared contract'),tr('المخطط والمحلل','Schema / parser'),tr('بصمة الخام','Raw hash'),tr('فشل التحليل','Parse failure'),tr('اكتمال الحقول','Field completeness'),tr('التأخر (وسيط / 95%)','Delay (median / p95)'),tr('الملاحظات','Issues')],d.sources.map(x=>[h(x.name),x.contract?`<span dir="ltr">${h(x.contract.connector)} ${h(x.contract.connector_version)} · ${h(x.contract.event_source)} · ${h(x.contract.time_zone)} · ${h(x.contract.clock_source)}</span>`:`<span class="pill warning">${tr('غير معلن','Not declared')}</span>`,`<span dir="ltr">${h(x.schema_versions.join(', ')||'—')} · ${h(x.parser_versions.join(', ')||'—')}</span>`,`${pc(x.raw_hash_pct)}${x.raw_record_hash_pct?' · '+tr('سطر خام','raw line')+' '+pc(x.raw_record_hash_pct):''}`,`<span class="pill ${x.parse_failure_pct>1?'danger':'success'}">${pc(x.parse_failure_pct)}</span> ${x.rejected_events} / ${x.accepted_events+x.rejected_events}${x.rejections.length?'<br><span dir="ltr">'+x.rejections.map(r=>h(r.code)+' ×'+r.events).join(', ')+'</span>':''}${x.log_lines?'<br>'+tr('سطور غير محللة','unparsed lines')+' '+pc(x.log_lines_unparsed_pct):''}`,x.completeness.map(c=>`<span dir="ltr">${h(c.kind)}</span> ${pc(c.field_completeness)}${c.most_missing.length?' ('+c.most_missing.map(m=>h(m.field)).join(', ')+')':''}`).join('<br>')||'—',`${n(x.delay_seconds.median)} / ${n(x.delay_seconds.p95)} ${tr('ث','s')}`,x.issues.map(i=>`<span class="pill warning">${dcIssue[i]||h(i)}</span>`).join(' ')||`<span class="pill success">${tr('سليم','OK')}</span>`]),'',{total:d.sources.length,limit:d.sources.length,offset:0})}
  <p class="secondary">${tr('يعلن الموصل عقده مع كل دفعة','A connector declares its contract with each batch')}: <span dir="ltr">{"contract":{"connector","connector_version","event_source","time_zone","clock_source"}}</span></p></div></section>`;}
