  if(action==='break-glass-request'){modal(tr('طلب وصول طوارئ مضبوط','Request controlled break-glass'),`<div class="hint">${tr('يلزم MFA حديث وموافقة مسؤول دائم آخر. لا يتجاوز الطلب 60 دقيقة أو 5 إجراءات ولا يتجاوز ضوابط سلامة الإجراء.','Recent MFA and another standing administrator are required. The grant is capped at 60 minutes and 5 actions and never bypasses action safety controls.')}</div><form data-form="break-glass"><div class="form-grid"><label>${tr('النطاق الضيق','Narrow scope')}<input name="scope" maxlength="300" required></label><label>${tr('المدة بالدقائق','Duration minutes')}<input name="duration_minutes" type="number" min="5" max="60" value="15" required></label><label>${tr('حد الإجراءات','Action cap')}<input name="max_actions" type="number" min="1" max="5" value="1" required></label><label class="full">${tr('سبب الطوارئ (20 حرفًا على الأقل)','Emergency reason (at least 20 characters)')}<textarea name="reason" minlength="20" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><button class="danger">${tr('إرسال لموافقة ثانية','Submit for second approval')}</button></form>`);return;}
