  if(action==='playbook-request'){const alerts=await api('/api/alerts?limit=100');modal(tr('طلب تشغيل Playbook منخفض الخطورة','Request low-risk playbook run'),alerts.items.length?`<div class="hint">${tr('الأتمتة تنشئ قضية تحقيق محلية فقط من لقطة الأدلة الحالية. تحتاج MFA حديثة وموافقة مسؤول دائم آخر، ولا تنفذ أي تغيير خارجي.','Automation creates only a local investigation case from the current evidence snapshot. It needs recent MFA and another standing administrator approval and performs no external change.')}</div><form data-form="playbook-run" data-id="${h(id)}"><div class="form-grid"><label>${tr('التنبيه','Alert')}<select name="alert_id">${alerts.items.map(alert=>`<option value="${h(alert.id)}">${h(alertTitle(alert.title))} · ${h(alert.severity)}</option>`).join('')}</select></label><label>${tr('صلاحية الموافقة بالثواني','Approval validity seconds')}<input name="ttl_seconds" type="number" min="300" max="3600" value="900" required></label><label class="full">${tr('سبب التشغيل','Run reason')}<textarea name="reason" minlength="10" maxlength="1000" required></textarea></label></div><div id="form-error" role="alert" hidden></div><button class="primary">${tr('إرسال لموافقة مستقلة','Submit for independent approval')}</button></form>`:`<div class="hint">${tr('لا يوجد تنبيه يمكن ربطه بالـPlaybook.','No alert is available to link to the playbook.')}</div>`);return;}
